import React, { useState, useEffect, useRef } from 'react';
import './NotificationBell.css';
import api from '../../services/api';

const NotificationBell = () => {
    const [notifications, setNotifications] = useState([]);
    const [isOpen, setIsOpen] = useState(false);
    const [unreadCount, setUnreadCount] = useState(0);
    const dropdownRef = useRef(null);

    // Загрузка уведомлений через новый API
    const loadNotifications = async () => {
        try {
            const response = await api.get('/notifications');
            const data = response.data || [];
            setNotifications(data);
            setUnreadCount(data.filter(n => !n.read).length);
        } catch (error) {
            console.error('Failed to load notifications', error);
        }
    };

    useEffect(() => {
        loadNotifications();
    }, []);

    // === WebSocket listener для уведомлений (реал-тайм) ===
    useEffect(() => {
        const handleNewNotification = (event) => {
            const notification = event.detail;
            if (!notification) return;

            // Добавляем новое уведомление в начало списка
            setNotifications(prev => [notification, ...prev]);

            // Увеличиваем счётчик непрочитанных
            if (!notification.read) {
                setUnreadCount(prev => prev + 1);
            }
        };

        window.addEventListener('newNotification', handleNewNotification);

        return () => {
            window.removeEventListener('newNotification', handleNewNotification);
        };
    }, []);

    useEffect(() => {
        const handleClickOutside = (event) => {
            if (dropdownRef.current && !dropdownRef.current.contains(event.target)) {
                setIsOpen(false);
            }
        };

        if (isOpen) {
            document.addEventListener('mousedown', handleClickOutside);
        }

        return () => {
            document.removeEventListener('mousedown', handleClickOutside);
        };
    }, [isOpen]);


    const markAsRead = async (id) => {
        try {
            await api.put(`/notifications/${id}/read`);
            setNotifications(prev =>
                prev.map(n => n.id === id ? { ...n, read: true } : n)
            );
            setUnreadCount(prev => Math.max(0, prev - 1));
        } catch (error) {
            console.error('Failed to mark as read', error);
        }
    };

    const markAllAsRead = async () => {
        try {
            await api.put('/notifications/read-all');
            setNotifications(prev => prev.map(n => ({ ...n, read: true })));
            setUnreadCount(0);
        } catch (error) {
            console.error('Failed to mark all as read', error);
        }
    };

    const handleNotificationClick = (notification) => {
        markAsRead(notification.id);

        // Переход по т��пу уведомления
        if (notification.type === 'event' && notification.relatedId) {
            // открыть вкладку событий
            const eventsTab = document.querySelector('[data-tab="scheduled"]');
            if (eventsTab) eventsTab.click();
        } else if (notification.relatedRoomSlug && notification.relatedRoomSlug.startsWith('questions-')) {
            // открыть вкладку Помощь
            const helpTab = document.querySelector('[data-tab="help"]');
            if (helpTab) helpTab.click();
        }
    };

    return (
        <div className="notification-bell-container" ref={dropdownRef}>
            <button
                className={`notification-bell-button ${unreadCount > 0 ? 'has-unread' : ''}`}
                onClick={() => {
                    setIsOpen(!isOpen);
                    if (!isOpen && unreadCount > 0) {
                        markAllAsRead();
                    }
                }}
                title="Уведомления"
            >
                🔔
                {unreadCount > 0 && (
                    <span className="notification-badge">{unreadCount > 99 ? '99+' : unreadCount}</span>
                )}
            </button>

            {isOpen && (
                <div className="notification-dropdown">
                    <div className="notification-header">
                        <h3>Уведомления</h3>
                        {notifications.length > 0 && (
                            <button className="clear-all" onClick={markAllAsRead}>
                                Прочитать все
                            </button>
                        )}
                    </div>

                    <div className="notification-list">
                        {notifications.length === 0 ? (
                            <div className="no-notifications">
                                <p>Нет уведомлений</p>
                            </div>
                        ) : (
                            notifications.map(notification => (
                                <div
                                    key={notification.id}
                                    className={`notification-item ${!notification.read ? 'unread' : ''}`}
                                    onClick={() => handleNotificationClick(notification)}
                                >
                                    <div className="notification-content">
                                        <div className="notification-title">{notification.title}</div>
                                        <div className="notification-message">{notification.message}</div>
                                        <div className="notification-time">
                                            {new Date(notification.createdAt).toLocaleString('ru-RU', {
                                                hour: '2-digit',
                                                minute: '2-digit'
                                            })}
                                        </div>
                                    </div>
                                </div>
                            ))
                        )}
                    </div>
                </div>
            )}
        </div>
    );
};

export default NotificationBell;
